//! Property tests: check rules that must hold for any input, using random
//! text generated by proptest.

use proptest::prelude::*;
use std::collections::HashMap;
use wfreq::core::{count_words, filter_by_length, merge_counts, stats, top_n};

/// Text made of short words from a small alphabet, mixed with punctuation,
/// capitals and some non-ASCII letters, so words repeat often.
fn text() -> impl Strategy<Value = String> {
    prop::collection::vec(
        prop_oneof![
            "[a-cA-C]{1,4}",
            "[a-c]{1,3}[,.!?]",
            "é[a-b]{0,2}",
            "--",
            "don't",
        ],
        0..60,
    )
    .prop_map(|words| words.join(" "))
}

fn counts() -> impl Strategy<Value = HashMap<String, usize>> {
    prop::collection::hash_map("[a-zé]{1,10}", 1usize..50, 0..40)
}

proptest! {
    /// Every token that keeps at least one character after cleaning is counted once.
    #[test]
    fn total_matches_number_of_real_words(input in text()) {
        let expected = input
            .split_whitespace()
            .filter(|t| t.chars().any(|c| c.is_alphanumeric() || c == '\''))
            .count();
        prop_assert_eq!(stats(&count_words(&input, false)).total, expected);
    }

    /// Without --case-sensitive, no counted word has an uppercase letter.
    #[test]
    fn case_insensitive_words_are_lowercase(input in text()) {
        for word in count_words(&input, false).keys() {
            prop_assert_eq!(word, &word.to_lowercase());
        }
    }

    /// top_n returns min(n, unique) words, ordered by count desc then word asc.
    #[test]
    fn top_n_is_sorted_and_sized(map in counts(), n in 0usize..60) {
        let top = top_n(&map, n);
        prop_assert_eq!(top.len(), n.min(map.len()));
        for pair in top.windows(2) {
            let (a, b) = (&pair[0], &pair[1]);
            prop_assert!(a.1 > b.1 || (a.1 == b.1 && a.0 < b.0), "{:?} before {:?}", a, b);
        }
        for (word, count) in &top {
            prop_assert_eq!(map.get(word), Some(count));
        }
    }

    /// Merging keeps every word and adds the totals.
    #[test]
    fn merge_adds_totals(a in counts(), b in counts()) {
        let expected = stats(&a).total + stats(&b).total;
        let mut merged = a.clone();
        merge_counts(&mut merged, b.clone());
        prop_assert_eq!(stats(&merged).total, expected);
        for word in a.keys().chain(b.keys()) {
            prop_assert!(merged.contains_key(word));
        }
    }

    /// The length filter keeps exactly the words inside min..=max characters.
    #[test]
    fn length_filter_keeps_exactly_in_range(map in counts(), min in 0usize..8, extra in 0usize..8) {
        let max = min + extra;
        let mut filtered = map.clone();
        filter_by_length(&mut filtered, min, Some(max));
        for (word, count) in &map {
            let len = word.chars().count();
            let kept = filtered.get(word);
            if (min..=max).contains(&len) {
                prop_assert_eq!(kept, Some(count));
            } else {
                prop_assert_eq!(kept, None);
            }
        }
    }
}
